"""Work around QSMxT 9.19.1 saving minIP data with the SWI dimensions."""
import json
from pathlib import Path
import sys

import nibabel as nib
import numpy as np


def write_minip(swi_path, output_path, window=7):
    source = nib.load(swi_path)
    if len(source.shape) != 3 or source.shape[2] < 1 or window < 1:
        raise ValueError(f"Invalid SWI shape or projection window: {source.shape}, {window}")
    # QSMxT'"'"'s default is a sliding seven-slice minimum along voxel axis 2.
    # Short acquisitions use one projection over all available slices.
    window = min(window, source.shape[2])
    data = source.get_fdata(dtype=np.float32)
    depth = source.shape[2] - window + 1
    projected = data[:, :, :depth].copy()
    for offset in range(1, window):
        np.minimum(projected, data[:, :, offset:offset + depth], out=projected)
    affine = source.affine.copy()
    # Locate each projected slice at the physical centre of its source slab.
    affine[:3, 3] += source.affine[:3, 2] * ((window - 1) / 2)
    header = source.header.copy()
    header.set_data_dtype(np.float32)
    result = nib.Nifti1Image(projected, affine, header)
    result.set_qform(affine, int(source.header['"'"'qform_code'"'"']) or 1)
    result.set_sform(affine, int(source.header['"'"'sform_code'"'"']) or 1)
    nib.save(result, output_path)
    # Read the complete payload: loading only the header missed this bug.
    check = nib.load(output_path)
    if check.shape != projected.shape or not np.array_equal(check.get_fdata(), projected, equal_nan=True):
        raise RuntimeError(f"minIP verification failed: {output_path}")
    return window


def repair_derivatives(root):
    for swi in Path(root).glob('"'"'sub-*/**/anat/*_swi.nii*'"'"'):
        if not (swi.name.endswith('"'"'.nii'"'"') or swi.name.endswith('"'"'.nii.gz'"'"')):
            continue
        output = swi.with_name(swi.name.replace('"'"'_swi.nii'"'"', '"'"'_minIP.nii'"'"'))
        window = write_minip(swi, output)
        sidecar = output.with_name(output.name.removesuffix('"'"'.gz'"'"').removesuffix('"'"'.nii'"'"') + '"'"'.json'"'"')
        metadata = json.loads(sidecar.read_text()) if sidecar.exists() else {}
        metadata.update(ProjectionWindowSlices=window, ProjectionAxis=2,
                        Description='"'"'Sliding minimum-intensity projection of SWI; slice positions are slab centres.'"'"')
        sidecar.write_text(json.dumps(metadata, indent=2) + '"'"'\n'"'"')
        print(f'"'"'Wrote valid minIP ({window}-slice slabs): {output.name}'"'"')


if __name__ == '"'"'__main__'"'"':
    repair_derivatives(sys.argv[1])
